#include <cstdint>
#include <cassert>

// Mock Slice for testing
class Slice {
public:
    Slice() : data_(""), size_(0) {}
    Slice(const char* d, size_t n) : data_(d), size_(n) {}
    Slice(const std::string& s) : data_(s.data()), size_(s.size()) {}
    const char* data() const { return data_; }
    size_t size() const { return size_; }
    Slice substr(size_t start, size_t n) const { return Slice(data_ + start, n); }
    std::string ToString() const { return std::string(data_, size_); }

private:
    const char* data_;
    size_t size_;
};

// Mock constants
const uint64_t kMaxSequenceNumber = (1ull << 56) - 1;
enum ValueType { kTypeDeletion = 0, kTypeValue = 1, kValueTypeForSeek = 2 };

bool ParseInternalKey(const Slice& internal_key, Slice* user_key, uint64_t* sequence, uint8_t* type) {
    if (internal_key.size() < 8) {
        return false;
    }
    if (user_key == nullptr || sequence == nullptr || type == nullptr) {
        return false;
    }

    // Extract user key (all bytes except last 8)
    size_t user_key_size = internal_key.size() - 8;
    *user_key = internal_key.substr(0, user_key_size);

    // Extract sequence and type from the last 8 bytes
    const char* trailer = internal_key.data() + user_key_size;
    uint64_t seq_and_type = 0;
    for (int i = 0; i < 8; i++) {
        seq_and_type |= static_cast<uint64_t>(static_cast<unsigned char>(trailer[i])) << (i * 8);
    }

    *sequence = seq_and_type >> 8;
    *type = seq_and_type & 0xFF;

    // Validate sequence number
    if (*sequence > kMaxSequenceNumber) {
        return false;
    }

    return true;
}

// Test cases
int main() {
    // Test 1: Valid internal key
    std::string internal_key_str = "user_key_123";
    uint64_t seq = 123456;
    uint8_t type = kTypeValue;
    uint64_t seq_and_type = (seq << 8) | type;
    std::string trailer(reinterpret_cast<const char*>(&seq_and_type), 8);
    Slice internal_key(internal_key_str + trailer);

    Slice user_key;
    uint64_t parsed_seq;
    uint8_t parsed_type;

    bool success = ParseInternalKey(internal_key, &user_key, &parsed_seq, &parsed_type);
    assert(success);
    assert(user_key.ToString() == "user_key_123");
    assert(parsed_seq == seq);
    assert(parsed_type == type);

    // Test 2: Internal key too short
    Slice short_key("short");
    success = ParseInternalKey(short_key, &user_key, &parsed_seq, &parsed_type);
    assert(!success);

    // Test 3: Nullptr outputs
    success = ParseInternalKey(internal_key, nullptr, &parsed_seq, &parsed_type);
    assert(!success);

    return 0;
}

